using Microsoft.EntityFrameworkCore;
using SolutionOne_DataAccessLayer.Entities;
using SolutionOne_DataAccessLayer.Repositories.HR.Interface;

namespace SolutionOne_DataAccessLayer.Repositories.HR.Implementation;

public class SalaryHeadMasterRepository : ISalaryHeadMasterRepository
{
    private readonly HrmsystemContext _hrmsystemContext;

    public SalaryHeadMasterRepository(HrmsystemContext hrmsystemContext)
    {
        _hrmsystemContext = hrmsystemContext;
    }

    public async Task<List<HrSalaryHeadMaster>> GetAllSalaryHeadMasters(long? companyMasterId)
    {
        var query = _hrmsystemContext.HrSalaryHeadMasters.AsNoTracking().AsQueryable();

        if (companyMasterId.HasValue && companyMasterId.Value > 0)
            query = query.Where(x => x.CompanyMasterId == companyMasterId.Value);

        return await query.OrderBy(x => x.Name).ToListAsync();
    }
}

