         INNER JOIN HR_SalaryHeadMaster sh ON sh.SalaryHeadMasterID = ews.SalaryHeadMasterID
         WHERE ews.EmployeeMasterID = @EmployeeID
           AND ews.CompanyMasterID  = @CompanyID
