        new { EmployeeID = employeeMasterId, CompanyID = companyMasterId });

    return rows.ToList();
}

/// <summary>The company's active "CTCSection" lookup values, in display order.</summary>
/// <remarks>
/// Guarded with OBJECT_ID: a database that has not run the Lookup Master script has neither
/// table, and the sheet must still print from the built-in wording rather than failing.
/// </remarks>
public async Task<List<CtcSectionLookupValue>> GetSectionValues(long companyMasterId)
{
    var connection = _hrmsystemContext.Database.GetDbConnection();

    var rows = await connection.QueryAsync<CtcSectionLookupValue>($@"
        IF OBJECT_ID('dbo.HR_LookupValue', 'U') IS NOT NULL
           AND OBJECT_ID('dbo.HR_LookupList', 'U') IS NOT NULL
            SELECT LTRIM(RTRIM(ISNULL(v.Code, '')))        AS Code,
                   LTRIM(RTRIM(v.Name))                    AS Name,
                   LTRIM(RTRIM(ISNULL(v.Description, ''))) AS Description,
                   v.DisplayOrder                          AS DisplayOrder
              FROM dbo.HR_LookupValue v
              JOIN dbo.HR_LookupList  l ON l.LookupListID = v.LookupListID
             WHERE l.ListCode = @List
               AND l.IsActive = 1
               AND v.IsActive = 1
               AND v.CompanyMasterID = @CompanyID
             ORDER BY v.DisplayOrder, v.Name",
        new { List = CtcSectionCatalogue.ListCode, CompanyID = companyMasterId });

    return rows.ToList();
}

